     1	package com.example.lending.domain;
     2	
     3	import com.example.lending.common.DateUtils;
     4	
     5	import java.time.LocalDate;
     6	import java.time.temporal.ChronoUnit;
     7	import java.util.Objects;
     8	import java.util.UUID;
     9	
    10	public class Loan {
    11	
    12	    static final int LOAN_PERIOD_DAYS = 14;
    13	    public static final int MAX_LOANS_PER_MEMBER = 5;
    14	    public static final int LATE_FEE_PER_DAY = 100;
    15	
    16	    private final UUID id;
    17	    private final UUID bookId;
    18	    private final UUID memberId;
    19	    private final LocalDate loanedAt;
    20	    private final LocalDate dueAt;
    21	    private LocalDate returnedAt;
    22	
    23	    private Loan(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt) {
    24	        this.id = Objects.requireNonNull(id, "id");
    25	        this.bookId = Objects.requireNonNull(bookId, "bookId");
    26	        this.memberId = Objects.requireNonNull(memberId, "memberId");
    27	        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
    28	        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
    29	        if (dueAt.isBefore(loanedAt)) {
    30	            throw new IllegalArgumentException("dueAt must not be before loanedAt");
    31	        }
    32	        this.returnedAt = returnedAt;
    33	    }
    34	
    35	    public static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt) {
    36	        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt, DateUtils.addDays(loanedAt, LOAN_PERIOD_DAYS), null);
    37	    }
    38	
    39	    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
    40	                                    LocalDate returnedAt) {
    41	        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt);
    42	    }
    43	
    44	    public void markReturned(LocalDate returnedAt) {
    45	        if (this.returnedAt != null) {
    46	            throw new LoanAlreadyReturnedException(id);
    47	        }
    48	        Objects.requireNonNull(returnedAt, "returnedAt");
    49	        if (returnedAt.isBefore(loanedAt)) {
    50	            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
    51	        }
    52	        this.returnedAt = returnedAt;
    53	    }
    54	
    55	    public boolean isReturned() {
    56	        return returnedAt != null;
    57	    }
    58	
    59	    public boolean isOverdue(LocalDate today) {
    60	        return today.isAfter(dueAt);
    61	    }
    62	
    63	    // 반납일이 기한 당일까지면 0일, 기한을 넘긴 날짜 수만큼 연체일이 된다
    64	    public long overdueDays() {
    65	        if (returnedAt == null) {
    66	            throw new IllegalStateException("loan " + id + " is not returned yet");
    67	        }
    68	        return Math.max(0, ChronoUnit.DAYS.between(dueAt, returnedAt));
    69	    }
    70	
    71	    public long lateFee() {
    72	        return overdueDays() * LATE_FEE_PER_DAY;
    73	    }
    74	
    75	    public UUID getId() {
    76	        return id;
    77	    }
    78	
    79	    public UUID getBookId() {
    80	        return bookId;
    81	    }
    82	
    83	    public UUID getMemberId() {
    84	        return memberId;
    85	    }
    86	
    87	    public LocalDate getLoanedAt() {
    88	        return loanedAt;
    89	    }
    90	
    91	    public LocalDate getDueAt() {
    92	        return dueAt;
    93	    }
    94	
    95	    public LocalDate getReturnedAt() {
    96	        return returnedAt;
    97	    }
    98	}
