    52	            throw new BookNotFoundException(command.bookId());
    53	        }
    54	        Book book = loadBookPort.loadBook(command.bookId())
    55	                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
    56	        if (book.getStatus() == BookStatus.ON_LOAN) {
    57	            throw new BookAlreadyOnLoanException(book.getId());
    58	        }
    59	        LocalDate loanedAt = command.loanedAt() != null ? command.loanedAt() : LocalDate.now();
    60	        Loan loan = Loan.start(book.getId(), member.getId(), loanedAt);
    61	        book.setStatus(BookStatus.ON_LOAN);
    62	        saveBookPort.saveBook(book);
    63	        saveLoanPort.saveLoan(loan);
    64	        return loan;
    65	    }
